 34→export const TextMessage: FC<Props> = ({
 35→  event,
 36→  isPreviousSameSender,
 37→  onMemberPress,
 38→}) => {
 39→  const [messageWidth, setMessageWidth] = useState(40);
 40→  const isUser = event.isOwn;
 41→  const sender = event.senderProfile;
 42→  const senderId = event.sender;
 43→  const [seenBy, setSeenBy] = useState<UserProfile[]>([]);
 44→  const content = getEventTextContent(event);
 45→  const setScrollToEventId = useSetAtom(TimelineAtoms.scrollToEventId);
 46→
 47→  const replyPayload = useMemo(() => {
 48→    if (event.content.tag !== TimelineItemContent_Tags.MsgLike) return null;
 49→
 50→    const inReplyTo = event.content.inner.content.inReplyTo;
 51→
 52→    if (!inReplyTo) return null;
 53→
 54→    const eventDetails = inReplyTo.event();
 55→    if (eventDetails.tag !== EmbeddedEventDetails_Tags.Ready) return null;
 56→
 57→    const senderName =
 58→      eventDetails.inner.senderProfile.tag === ProfileDetails_Tags.Ready
 59→        ? (eventDetails.inner.senderProfile.inner.displayName ??
 60→          eventDetails.inner.sender)
 61→        : eventDetails.inner.sender;
 62→
 63→    let mediaSource: { source: MediaSourceInterface; mimetype: string } | null =
 64→      null;
 65→    const replyContent = eventDetails.inner.content;
 66→
 67→    if (replyContent.tag === TimelineItemContent_Tags.MsgLike) {
 68→      const kind = replyContent.inner.content.kind;
 69→      if (kind?.tag === MsgLikeKind_Tags.Message) {
 70→        const msgType = kind.inner.content.msgType;
 71→        if (msgType?.tag === MessageType_Tags.Image) {
 72→          mediaSource = {
 73→            source: msgType.inner.content.source,
 74→            mimetype: msgType.inner.content.info?.mimetype || "image/jpeg",
 75→          };
 76→        } else if (msgType?.tag === MessageType_Tags.Video) {
 77→          mediaSource = {
 78→            source: msgType.inner.content.source,
 79→            mimetype: msgType.inner.content.info?.mimetype || "video/mp4",
 80→          };
 81→        }
 82→      }
 83→    }
 84→
 85→    return {
 86→      eventId: inReplyTo.eventId(),
 87→      senderName,
 88→      content: getMessageTextContent(eventDetails.inner.content),
 89→      mediaSource,
 90→    };
 91→  }, [event]);
 92→
 93→  const handleReplyPress = useCallback(() => {
 94→    if (replyPayload) setScrollToEventId(replyPayload.eventId);
 95→  }, [replyPayload, setScrollToEventId]);
 96→
 97→  useEffect(() => {
 98→    MatrixService.getReadReceipts(event)
 99→      .then(setSeenBy)
100→      .catch((error) => {
101→        console.error("Failed to get read receipt users:", error);
102→        setSeenBy([]);
103→      });
104→  }, [event]);
105→
106→  return (
107→    <Block
108→      align={isUser ? "flex-end" : "flex-start"}
109→      margins={{ marginTop: isPreviousSameSender ? 6 : 16 }}
110→    >
111→      <MessageSender
112→        sender={sender}
113→        senderId={senderId}
114→        isUser={isUser}
115→        isPreviousSameSender={isPreviousSameSender}
116→        onMemberPress={onMemberPress}
117→      />
118→      <MessageLongPressWrapper event={event} content={content}>
119→        <Block
120→          paddings={12}
121→          background={isUser ? Colors.primary : Colors.message}
122→          border={{ borderRadius: 24 }}
123→          align="stretch"
124→          gap={12}
125→          onLayout={(e) => setMessageWidth(e.nativeEvent.layout.width)}
126→        >
127→          <ReplyPayload
128→            replyPayload={replyPayload}
129→            onPress={handleReplyPress}
130→          />
131→          <Block
132→            justify="space-between"
133→            align="center"
134→            flex={{ flexWrap: "wrap" }}
135→            flexDirection={isUser ? "row-reverse" : "row"}
136→            gap={{
137→              row: 4,
138→              col: 16,
139→            }}
140→            // Some short strings (e.g., "aa", "ai") wrap unexpectedly, while others ("dd", "a") do not.
141→            // Add this value to prevent unwanted wrapping for short text.
142→            minWidth={64}
143→          >
144→            <Text size={TextSize.small} color="white">
145→              {content}
146→            </Text>
147→            <Block
148→              flexDirection={isUser ? "row" : "row-reverse"}
149→              gap={4}
150→              align="center"
151→            >
152→              <PinIndicator event={event} />
153→              <Text size={TextSize.tiny} color={Colors.white50}>
154→                {format(Number(event.timestamp), "HH:mm")}
155→              </Text>
156→            </Block>
157→          </Block>
158→          {isPreviousSameSender && (
159→            <Block
160→              absolute
161→              offsets={
162→                isUser
163→                  ? {
164→                      right: 6,
165→                      bottom: 2,
166→                    }
167→                  : {
168→                      left: 6,
169→                      bottom: 2,
170→                    }
171→              }
172→            >
173→              <Image
174→                source={
175→                  isUser
176→                    ? require("assets/icons/polygon.png")
177→                    : require("assets/icons/guest-polygon.png")
178→                }
179→                width={7}
180→                height={6}
181→                style={styles.polygon}
182→              />
183→            </Block>
184→          )}
185→        </Block>
186→      </MessageLongPressWrapper>
187→      <SeenBy seenBy={seenBy} messageWidth={messageWidth} />
188→    </Block>
189→  );
190→};
191→
192→const styles = StyleSheet.create({
193→  polygon: {
194→    width: 7,
195→    height: 6,
196→  },
197→});
